 "title": "Preanalytical phase of biochemical analyses",
 "sourceFile": "1 Preanalytical phase of Biochemical analyzes.pdf (Clinical Biochemistry, Prof. Nabiha Kamal)",
 "sourceUrl": "https://drive.google.com/file/d/1dIG2eLH2KA9Q74BGxk9ZJVan6HQncfQ5/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Most wrong lab results are not wrong analyses: <strong>68 percent</strong> of errors happen before the sample reaches the analyser. The preanalytical phase covers the prescription, the patient, the equipment, the sampling and the transport.</p>"
  },
  {
   "id": "s1",
   "title": "The prescription",
   "html": "<p>Give the <strong>time</strong> (cortisol, thyroid hormones, adrenaline vary daily), <strong>sex</strong>, <strong>age</strong> (ALP higher in children) and <strong>pregnancy</strong> (ALP up; proteins, iron, ferritin down by haemodilution). For an infusion, sample the <strong>opposite arm</strong> and state the infusion.</p>"
  },
  {
   "id": "s2",
   "title": "The patient",
   "html": "<p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Factor</th><th scope='col'>Rule</th></tr></thead><tbody><tr><th scope='row'>Posture</th><td>Rest 15 min in the same position</td></tr><tr><th scope='row'>Exercise</th><td>12 hours of rest (CK can quadruple)</td></tr><tr><th scope='row'>Fasting</th><td>At least 8 h, sample 7 to 9 a.m. (lipids +21 percent otherwise)</td></tr><tr><th scope='row'>Stress</th><td>Raises prolactin, adrenaline, cortisol</td></tr></tbody></table></div></p>"
  },
  {
   "id": "s3",
   "title": "Equipment and technique",
   "html": "<p>Equipment carries a <strong>CE or FDA</strong> mark and meets EN/MN 14820. <strong>Tourniquet</strong>: 7 to 10 cm above, not tight, off within 1 minute (up to 10 percent error otherwise). <strong>Tubes</strong>: respect the order, never transfer blood, respect the fill (citrate 1:4), mix 5 to 10 times. Label immediately and check identity.</p>"
  },
  {
   "id": "s4",
   "title": "Transport and haemolysis",
   "html": "<p>Upright; analyse within <strong>2 hours</strong> (glucose falls; potassium and transaminases rise); store at 4 to 8°C; protect <strong>bilirubin</strong> from light. <strong>Haemolysis</strong> from tourniquet, syringe turbulence, agitation or delay falsely raises potassium and intracellular enzymes.</p>"
  }
 ],
