 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Name the catecholamines and their roles.",
   "back": "Adrenaline (80 percent of adult secretion), noradrenaline and dopamine. They drive the immediate stress response, meet needs such as exercise, and keep blood pressure and glucose stable, protecting vital functions."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Why is the adrenal medulla a modified sympathetic ganglion?",
   "back": "Embryology: from the neural crest, like sympathetic ganglia. Histology: chromaffin cells in clusters around capillaries. Neurophysiology: catecholamines are also neurotransmitters of nerve cells."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Give the catecholamine synthesis pathway.",
   "back": "Phenylalanine (phenylalanine hydroxylase) to tyrosine; tyrosine hydroxylase to dopa, the feedback step; decarboxylase to dopamine; dopamine beta-hydroxylase to noradrenaline; PNMT to adrenaline."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "How is catecholamine secretion regulated?",
   "back": "Stimulated by the sympathetic system via splanchnic nerves: reflex (low BP, hypoxia, hypercapnia), central (hypoglycaemia, hypothermia), intercentral (pain, emotion, stress, exercise). Hormones: ACTH (dopa, noradrenaline) and cortisol (adrenaline, noradrenaline). Feedback on CNS centres, carotids and tyrosine hydroxylase."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Describe the adrenergic receptors.",
   "back": "Alpha receptors outnumber beta, but beta have higher affinity for adrenaline. Beta-1: heart rate and force, lipolysis. Beta-2: renin, hepatic glycogenolysis, smooth muscle relaxation. Alpha-1: vasoconstriction, sphincter contraction. Alpha-2: presynaptic inhibition of noradrenaline release."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What do catecholamines do to organs?",
   "back": "Heart: positive chronotropic and inotropic, more venous return; vasodilation in muscle and coronaries, vasoconstriction in gut, kidney, skin; higher output, BP and oxygen use. Gut: less motility. Uterus: beta-2 relaxes (tocolysis), alpha contracts. Bronchi: dilation. Eye: mydriasis. Bladder wall relaxes, sphincter contracts. Muscle: tone up, fatigue delayed. Glands inhibited except sweat."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "Give the metabolic actions of catecholamines.",
   "back": "Mainly via beta receptors: muscle glycogenolysis and inhibition of insulin (mild hyperglycaemia), lipolysis, hyperkalaemia, thermogenesis with cutaneous vasoconstriction."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "How are catecholamines inactivated and eliminated?",
   "back": "Uptake into nerve endings and storage. Chemical: COMT (70 percent) methylates circulating catecholamines to metanephrine and normetanephrine; MAO (20 percent) deaminates noradrenaline in nerve endings. After hepatic conjugation, urine contains VMA 80 percent (2 to 4 mg/day), metanephrines 10 to 15 percent, free catecholamines 5 percent, little MHPG."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Pheochromocytoma versus neuroblastoma.",
   "back": "Pheochromocytoma: 90 percent benign, 90 percent adrenal, adults 20 to 50, hypertension (70 percent permanent, 30 percent in fits), excess catecholamines and metanephrines; test plasma metanephrines. Neuroblastoma: malignant, early childhood, adrenal, abdominal or thoracic, non-specific signs, lacks PNMT so dopamine accumulates; test 24-hour urinary dopamine and VMA, plasma NSE."
  }
 ],
 "deeper": [
  {
   "title": "Why adrenaline is given in anaphylaxis",
   "html": "<p>Adrenaline hits alpha-1 receptors, constricting vessels and raising blood pressure, and beta-2 receptors, opening the bronchi. In anaphylaxis the patient has dangerously low blood pressure and narrowed airways at once, so one drug reverses both.</p><p class='src'>Source: the lecture's receptor actions and conclusion slides.</p>"
  }
 ],
