 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "Name the four types of steroid hormones.",
   "back": "Glucocorticoids (cortisol), mineralocorticoids (aldosterone), androgens (testosterone) and female hormones (oestradiol, progesterone). All derive from cholesterol via pregnenolone; each tissue's enzymes decide which it makes."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Which organs make steroids?",
   "back": "Adrenal cortex: glomerular (mineralocorticoids), fascicular (mainly glucocorticoids), reticular (androgens from DHEA). Ovaries: oestrogens in the follicular phase, progesterone from the corpus luteum. Testes: Leydig cells make testosterone (95 percent of the total); Sertoli cells support sperm. Placenta: oestrogens and progesterone."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "How do ovarian cells cooperate?",
   "back": "Theca cells make androgens; granulosa cells convert them to oestradiol. After ovulation, luteal cells secrete progesterone, which theca cells can turn into androstenedione and testosterone, and granulosa cells into oestradiol."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Classify steroids by carbon number.",
   "back": "C18 oestrogens: E1 oestrone (menopause), E2 oestradiol (active women), E3 oestriol (pregnancy only). C19 androgens: DHEA and DHEA-S (adrenal), androstenedione (adrenal and gonads), testosterone, and DHT (most potent). C21: progesterone, cortisol, aldosterone."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Name the steroidogenic enzymes.",
   "back": "Hydroxylases (add OH), desmolases (cut carbon bonds after hydroxylation), and the dehydrogenase + isomerase pair (remove two hydrogens, shift a double bond)."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "Describe the common stage of synthesis.",
   "back": "In mitochondria, a hydroxylase acts on carbons 20 and 22 and cholesterol 20-22 desmolase cuts the chain, giving pregnenolone. The desmolase is the key enzyme, stimulated by ACTH (adrenal) and LH and FSH (gonads). In microsomes, 17-alpha-hydroxylase and 3-beta dehydrogenase-isomerase give 17-OH pregnenolone, progesterone and 17-OH progesterone."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "How is cortisol made and cleared?",
   "back": "In the fascicular zone, from 17-OH progesterone by 21-hydroxylase then 11-beta-hydroxylase. About 20 mg/day, inactivated in the liver to cortisone by 11-beta-dehydrogenase."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Explain congenital adrenal hyperplasia.",
   "back": "Inherited 21-hydroxylase deficiency: 17-OH progesterone accumulates and is diverted to DHEA and androgens; cortisol and aldosterone fall. Without cortisol feedback, ACTH rises, the desmolase is overactive and the cortex hypertrophies. At birth: ambiguous genitalia in girls; later: salt-losing dehydration, primary amenorrhoea, early puberty, hirsutism. Steroids before week 6 of amenorrhoea prevent virilisation."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "How is aldosterone made?",
   "back": "Only in the glomerular zone, via progesterone: 21-hydroxylase gives deoxycorticosterone (weak mineralocorticoid), 11-beta-hydroxylase gives corticosterone, then 18-hydroxylation and dehydrogenation give aldosterone, the main regulator of electrolyte balance."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "What is the progesterone receptor mutation case?",
   "back": "A rare genetic gestational hypertension: the mutated aldosterone receptor recognises progesterone, normally an anti-mineralocorticoid, as a potent agonist; pregnancy's high progesterone then causes hypertension."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Describe androgen synthesis.",
   "back": "Adrenal (mainly reticular zone): DHEA, circulating as DHEA sulphate; only 1 percent of testosterone. Gonadal: testosterone from androstenedione from puberty, mainly testes. Androstenedione from adrenal DHEA and gonads leads to testosterone and oestrogens."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Describe oestrogen synthesis.",
   "back": "Requires androgens: oestradiol from testosterone, oestrone from androstenedione, by aromatase. Ovaries (oestradiol 50 to 70 percent before menopause, protecting bone) and placenta (oestriol). After menopause fat takes over and oestrone is 99 percent; obesity raises breast cancer risk."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "Describe steroid hormones in pregnancy.",
   "back": "Oestrogen, progesterone, cortisol and testosterone rise. First trimester: the corpus luteum, driven by HCG. Second and third: the feto-placental unit; fetal adrenal DHEA is hydroxylated by the fetal liver and converted by the placenta to oestriol; the placenta also makes progesterone."
  },
  {
   "id": "c13",
   "type": "text",
   "front": "Give the roles of cortisol.",
   "back": "Stress hormone, highest in the morning: catabolism of carbohydrates, fats and proteins, sodium retention, nerve excitability, bone breakdown, anti-inflammatory. In pregnancy: fetal liver glycogen and lung surfactant; lack in preterm babies causes hyaline membrane disease."
  },
  {
   "id": "c14",
   "type": "text",
   "front": "Give the roles of aldosterone, oestrogens, progesterone and androgens.",
   "back": "Aldosterone: distal tubule sodium retention, potassium loss, higher volume and BP (with renin-angiotensin). Oestrogens: metabolism, osteoblasts, water retention, secondary sex traits, uterine excitability; their postpartum fall triggers prolactin. Progesterone: implantation, uterine quieting, anti-oestrogenic, opposes lactogenesis in pregnancy. Androgens: protein anabolism, spermatogenesis, male traits, oestrogen precursors, fetal genital differentiation."
  },
  {
   "id": "c15",
   "type": "text",
   "front": "How is steroidogenesis regulated?",
   "back": "Hypothalamus: CRH and GnRH. Anterior pituitary: ACTH (corticotroph cells) acts on the adrenal cortex (cortisol, aldosterone, adrenal androgens); FSH on gonads (oestrogens); LH on gonads (progesterone). Hormones feed back negatively."
  }
 ],
 "deeper": [
  {
   "title": "Why a blocked enzyme makes girls look male",
   "html": "<p>In 21-hydroxylase deficiency the adrenal cannot finish cortisol. With no cortisol, the pituitary keeps pushing ACTH, which drives the whole pathway harder. Precursors pile up before the block and spill into the one route still open, the androgen pathway, flooding the fetus with androgens.</p><p class='src'>Source: the lecture's 21-hydroxylase deficiency slides.</p>"
  }
 ],
