 "id": "biochem-cardiac",
 "subject": "biochem",
 "group": "Organ exploration",
 "title": "Cardiac biochemical exploration",
 "sourceFile": "7 Cardiac biochemical exploration.pdf (Clinical Biochemistry, Prof. Nabiha Kamal)",
 "sourceUrl": "https://drive.google.com/file/d/13taA5XP43nsiLkk-ML-vlBXOtxqeLm4r/view?usp=drivesdk",
 "buildNote": "<strong>Built from the lecture slides.</strong> If your professor says something different, trust your professor.",
 "summary": [
  {
   "id": "s0",
   "title": "The big picture",
   "html": "<p>Three questions, three markers: <strong>Is this an infarction?</strong> Troponin. <strong>Is this heart failure?</strong> BNP or NT-proBNP. <strong>What is the long-term coronary risk?</strong> Ultrasensitive CRP.</p>"
  },
  {
   "id": "s1",
   "title": "Troponins",
   "html": "<p>Old markers (myoglobin, CPK, CK-MB, AST, LDH) are not specific. Cardiac troponins <strong>T and I</strong> are; troponin C is shared by all muscle.</p><div class='table-wrap'><table class='wide'><thead><tr><th scope='col'>Timing</th><th scope='col'>Value</th></tr></thead><tbody><tr><th scope='row'>Rise (high-sensitivity)</th><td>2 hours</td></tr><tr><th scope='row'>Rise (conventional)</th><td>4 hours</td></tr><tr><th scope='row'>Peak</th><td>About 14 hours</td></tr><tr><th scope='row'>cTnI stays up</th><td>75 to 140 hours</td></tr><tr><th scope='row'>cTnT stays up</th><td>Over 10 days</td></tr></tbody></table></div><p>Also raised in myocarditis, toxicity, pericarditis. Assays are not standardised: use one lab.</p>"
  },
  {
   "id": "s2",
   "title": "Natriuretic peptides",
   "html": "<p><strong>BNP</strong> and <strong>NT-proBNP</strong> from cardiomyocytes are diuretic, natriuretic and vasodilator. They diagnose chronic heart failure, but rise with age and in women, fall with high BMI, and NT-proBNP is distorted in <strong>renal failure</strong>. Keep the same peptide and lab.</p>"
  },
  {
   "id": "s3",
   "title": "Ultrasensitive CRP",
   "html": "<p>CRP: liver, IL-6; rises at 6 to 7 h, peaks at <strong>48 to 72 h</strong>, normal by one week. A persistent low CRP signals <strong>cardiovascular risk</strong>.</p>"
  }
 ],
