 "cards": [
  {
   "id": "c0",
   "type": "text",
   "front": "What does the nephron do?",
   "back": "Regulates water-electrolyte and acid-base balance, eliminates toxins, and makes renin, erythropoietin and active vitamin D."
  },
  {
   "id": "c1",
   "type": "text",
   "front": "Describe serum creatinine.",
   "back": "A muscle creatine waste product reflecting muscle mass and GFR, independent of diet and hydration. Sample in the morning, avoid haemolysis and bilirubin, moderate fasting. Men 9 to 12, women 6 to 11, children 3 to 8 mg/L."
  },
  {
   "id": "c2",
   "type": "text",
   "front": "Describe urea.",
   "back": "Made by the liver from protein-derived ammonia; depends on filtration, fluid intake, dietary protein and catabolism. Sample fasting. 0.15 to 0.45 g/L."
  },
  {
   "id": "c3",
   "type": "text",
   "front": "Describe cystatin C.",
   "back": "Produced by all cells; more accurate than creatinine, stable from 3 months to 70 years, less affected by sex and muscle. Useful in low muscle mass, early acute renal failure and tubulopathies. Costly, second-line; corticosteroids raise it. 0.5 to 1 mg/L."
  },
  {
   "id": "c4",
   "type": "text",
   "front": "Describe uric acid.",
   "back": "End product of purines, varying with diet, age and time of day; rises in renal failure, not always with urea and creatinine. Sample fasting after 3 purine-free days; avoid grey (fluoride-oxalate) tubes. Men 30 to 70, women 20 to 60, children 10 to 35 mg/L."
  },
  {
   "id": "c5",
   "type": "text",
   "front": "What does the plasma ionogram show?",
   "back": "Sodium (osmolality), potassium (hyperkalaemia in acute renal failure, life-threatening above 6.5 mmol/L), bicarbonate (acidosis in chronic failure), osmolality [(Na + K) x 2] + urea + glucose = 290 ± 5."
  },
  {
   "id": "c6",
   "type": "text",
   "front": "What calcium-phosphate changes occur in chronic renal failure?",
   "back": "Calcium falls, phosphate and PTH rise: renal osteodystrophy with osteomalacia and secondary hyperparathyroidism, because the kidney can no longer activate vitamin D."
  },
  {
   "id": "c7",
   "type": "text",
   "front": "Classify urine volume.",
   "back": "Normal 0.75 to 2 L/day. Polyuria over 2.5 L (renal failure, diabetes insipidus). Oliguria under 0.6 L. Anuria under 0.1 L (acute renal failure). A normal volume does not mean normal function."
  },
  {
   "id": "c8",
   "type": "text",
   "front": "Describe proteinuria and microalbuminuria.",
   "back": "Screen with strips (qualitative), confirm in 24-hour urine. Physiological 50 to 150 mg/24 h; functional (orthostatism, effort, hypertension) moderate and intermittent; pathological over 150 mg/24 h and permanent. Microalbuminuria 30 to 300 mg/24 h predicts nephropathy, e.g. diabetic."
  },
  {
   "id": "c9",
   "type": "text",
   "front": "What do other urine tests show?",
   "back": "Natriuresis and kaliuresis (Na/K over 1); urinary creatinine 1 to 2 g/24 h for clearance; urinary urea and uric acid (intake, catabolism, concentrating power); urinary calcium and phosphate (stones, secondary hyperparathyroidism)."
  },
  {
   "id": "c10",
   "type": "text",
   "front": "Explain clearance and creatinine clearance.",
   "back": "Clearance = U x V / P, the plasma volume cleared per unit time; for a substance neither reabsorbed nor secreted it equals GFR. Creatinine clearance = urinary creatinine / serum creatinine x urine flow, normalised to 1.73 m²: men 130 ± 20, women 110 ± 20 mL/min. Errors come from incomplete collection; MDRD formulas avoid this."
  },
  {
   "id": "c11",
   "type": "text",
   "front": "Stage chronic renal failure by clearance.",
   "back": "Moderate 50 to 70 mL/min (usually silent); significant 20 to 50; severe 5 to 20 (most biological disorders); under 5: dialysis or transplant."
  },
  {
   "id": "c12",
   "type": "text",
   "front": "How are tubular functions tested?",
   "back": "Osmolar clearance = OsmU x V / OsmP. Concentration test: overnight water fast, morning urine over 800 mOsm/kg. Dilution test: 20 mL/kg water load, one sample near 100 mOsm/kg, 50 percent excreted in 2 hours, 80 percent in 5. Acid-base: bicarbonate reabsorption, titratable acid and ammonia excretion."
  }
 ],
 "deeper": [
  {
   "title": "Why a normal creatinine can hide kidney disease",
   "html": "<p>Creatinine reflects muscle mass as well as filtration. An elderly, thin woman makes little creatinine, so her level can look normal while her GFR has already fallen by half. That is why estimated GFR formulas adjust for age and sex, and why cystatin C helps in people with low muscle mass.</p><p class='src'>Source: the lecture's creatinine and cystatin C slides.</p>"
  }
 ],
